oxy_webhelp_navlinks = {"exocompute_for_aws-d39307e16840":{"topics":[{"title":"Introduction to Exocompute on AWS","shortdesc":"<p class=\"shortdesc\">Describes common Exocompute terminology and a workflow example to\n                                help you plan and set up Exocompute on AWS.<\/p>","href":"saas\/aws_exocompute_workflow_example.html","menu":{"hasChildren":false},"tocID":"tocId-d39307e16857","next":"tocId-d39307e16857"},{"title":"Evaluate Exocompute on AWS options","shortdesc":"<p class=\"shortdesc\">When setting up Exocompute on AWS for the accounts onboarded using the self-managed         deployment model, it is important to evaluate the options for deployment and networking.         Thorough evaluation of these choices helps to align them with the needs of your organization         prior to Exocompute configuration.<\/p>","href":"saas\/aws_exocompute_evaluate_options.html","attributes":{"data-id":"aws_exocompute_evaluate_options"},"menu":{"hasChildren":false},"tocID":"aws_exocompute_evaluate_options-d39307e16883","next":"aws_exocompute_evaluate_options-d39307e16883"},{"title":"Prerequisites for Exocompute on AWS","shortdesc":"<p class=\"shortdesc\">Before configuring Exocompute in AWS regions for an AWS account onboarded using the         self-managed deployment model, where you provision and manage compute resources such as         Exocompute in your own AWS account, ensure you have established a robust network setup and         addressed encryption key requirements to enable secure communication and data         protection.<\/p>","href":"saas\/aws_prereq_exocompute.html","attributes":{"data-id":"aws_prereq_exocompute"},"menu":{"hasChildren":false},"tocID":"aws_prereq_exocompute-d39307e16949","next":"aws_prereq_exocompute-d39307e16949"},{"title":"Configure Exocompute on AWS","shortdesc":"<p class=\"shortdesc\">The configuration workflow sequence for localized and centralized Exocompute on             AWS,<span class=\"ph\"> AWS accounts onboarded using the self-managed deployment             model<\/span>, Rubrik-hosted Elastic Container Registry, and Rubrik-managed Elastic         Kubernetes Service cluster.<\/p>","href":"saas\/aws_configuration_exocompute.html","attributes":{"data-id":"aws_configuration_exocompute"},"menu":{"hasChildren":false},"tocID":"aws_configuration_exocompute-d39307e17203","next":"aws_configuration_exocompute-d39307e17203"},{"title":"Private Container Registry for AWS","shortdesc":"<p class=\"shortdesc\">For security purposes, when you do not want to retrieve Docker images from a registry         hosted by Rubrik, you can configure a Private Container Registry to retrieve these Docker         images from a registry hosted by you.<\/p>","href":"saas\/private_container_registry.html","attributes":{"data-id":"private_container_registry"},"menu":{"hasChildren":false},"tocID":"private_container_registry-d39307e17295","next":"private_container_registry-d39307e17295"},{"title":"Exocompute health check for AWS","shortdesc":"<p class=\"shortdesc\">The Exocompute health check for AWS is a feature in <span class=\"ph\">RSC<\/span> that runs a         health check for an Elastic Kubernetes Service cluster immediately after its configuration         and displays the relevant status.<\/p>","href":"saas\/aws_exocompute_health_check.html","attributes":{"data-id":"aws_exocompute_health_check"},"menu":{"hasChildren":false},"tocID":"aws_exocompute_health_check-d39307e17328","next":"aws_exocompute_health_check-d39307e17328"},{"title":"Viewing Exocompute events","shortdesc":"<p class=\"shortdesc\">View the Events page from the Dashboard to see the Exocompute events.<\/p>","href":"saas\/viewing_exo_health_check_events.html","attributes":{"data-id":"viewing_exo_health_check_events"},"menu":{"hasChildren":false},"tocID":"viewing_exo_health_check_events-d39307e17353","next":"viewing_exo_health_check_events-d39307e17353"},{"title":"Maintain Exocompute on AWS","shortdesc":"<p class=\"shortdesc\">Maintaining Exocompute on AWS involves regularly reviewing and updating settings and         removing obsolete configurations to ensure optimal performance and resource         management.<\/p>","href":"saas\/aws_maintenance_exocompute.html","attributes":{"data-id":"aws_maintenance_exocompute"},"menu":{"hasChildren":false},"tocID":"aws_maintenance_exocompute-d39307e17375","next":"aws_maintenance_exocompute-d39307e17375"},{"title":"Best practices for reducing Exocompute on AWS costs","shortdesc":"<p class=\"shortdesc\">You can configure your AWS network and storage settings to avoid unexpected costs         when using Exocompute on AWS for archiving and data protection operations.<\/p>","href":"saas\/aws_exo_cost_best_practices.html","attributes":{"data-id":"aws_exo_cost_best_practices"},"menu":{"hasChildren":false},"tocID":"aws_exo_cost_best_practices-d39307e17430","next":"aws_exo_cost_best_practices-d39307e17430"}]}};